#!/usr/bin/env bash
set -euo pipefail

ROOT="${1:-${PROJECT_ROOT:-.}}"
APP="$ROOT/memeflow-app"
[[ -f "$APP/index.html" ]] || APP="$ROOT"
INDEX="$APP/index.html"

[[ -f "$INDEX" ]] || {
  echo "ERROR: index.html not found. Run from ~/workspace."
  exit 1
}

DIR="$APP/.memeflow-patches/mobile-module-spacing-v2"
mkdir -p "$DIR"

STAMP="$(date +%Y%m%d-%H%M%S)"
BACKUP="$DIR/index.html.$STAMP.bak"
WORK="$DIR/index.html.$STAMP.work"
PYTMP="$DIR/install.$STAMP.py"
REPORT="$DIR/report.$STAMP.txt"

cp "$INDEX" "$BACKUP"
cp "$INDEX" "$WORK"

rollback(){
  cp "$BACKUP" "$INDEX" 2>/dev/null || true
  rm -f "$WORK" "$PYTMP"
}

trap 'echo "ERROR: MOBILE MODULE SPACING V2 failed; restoring exact pre-install index.html."; rollback' ERR

printf '%s' '' | base64 -d > "$PYTMP"
python3 "$PYTMP" "$WORK" | tee "$REPORT"

cp "$WORK" "$INDEX"
rm -f "$WORK" "$PYTMP"

cat > "$DIR/latest-manifest.txt" <<EOF
INDEX=$INDEX
BACKUP=$BACKUP
REPORT=$REPORT
EOF

trap - ERR

echo
echo "OK: MOBILE MODULE SPACING V2 installed."
echo "V1 was REPLACED inside the same canonical mobile style owner."
echo "All page-flow/module-wrapper vertical rhythm is now 10px."
echo
echo "Now Stop -> Run, then hard-refresh Safari."
